changeSet.sql:
-- Aggregate duplicate candidate state into the oldest PENDING row. WITH duplicate_groups AS ( SELECT customer_id, fact_type, fact_key, normalized_value, min(id) AS keep_id, min(first_seen_at) AS first_seen_at, max(last_seen_at) AS last_seen_at, max(expires_at) AS expires_at, max(max_confidence) AS max_confidence FROM customer_memory_candidate WHERE status = 'PENDING' GROUP BY customer_id, fact_type, fact_key, normalized_value HAVING count(*) > 1 ) UPDATE customer_memory_candidate c SET first_seen_at = g.first_seen_at, last_seen_at = g.last_seen_at, expires_at = g.expires_at, max_confidence = g.max_confidence FROM duplicate_groups g WHERE c.id = g.keep_id;
-- Move evidence from duplicate candidates onto the canonical PENDING candidate. WITH duplicate_groups AS ( SELECT customer_id, fact_type, fact_key, normalized_value, min(id) AS keep_id FROM customer_memory_candidate WHERE status = 'PENDING' GROUP BY customer_id, fact_type, fact_key, normalized_value HAVING count(*) > 1 ), duplicate_candidates AS ( SELECT c.id AS duplicate_id, g.keep_id FROM customer_memory_candidate c JOIN duplicate_groups g ON g.customer_id = c.customer_id AND g.fact_type = c.fact_type AND g.fact_key = c.fact_key AND g.normalized_value = c.normalized_value WHERE c.status = 'PENDING' AND c.id <> g.keep_id ) UPDATE customer_memory_candidate_evidence e SET candidate_id = d.keep_id FROM duplicate_candidates d WHERE e.candidate_id = d.duplicate_id;
-- Merge duplicated evidence values into the oldest evidence row. WITH evidence_groups AS ( SELECT candidate_id, chat_id, min(id) AS keep_id, max(expires_at) AS expires_at, max(confidence) AS confidence, max(episode_id) AS episode_id FROM customer_memory_candidate_evidence GROUP BY candidate_id, chat_id HAVING count(*) > 1 ) UPDATE customer_memory_candidate_evidence e SET expires_at = g.expires_at, confidence = g.confidence, episode_id = coalesce(g.episode_id, e.episode_id) FROM evidence_groups g WHERE e.id = g.keep_id;
WITH ranked AS ( SELECT id, row_number() OVER ( PARTITION BY candidate_id, chat_id ORDER BY id ASC ) AS rn FROM customer_memory_candidate_evidence ) DELETE FROM customer_memory_candidate_evidence e USING ranked r WHERE e.id = r.id AND r.rn > 1;
-- Preserve duplicate candidate rows as history, but only one remains PENDING. WITH ranked AS ( SELECT id, row_number() OVER ( PARTITION BY customer_id, fact_type, fact_key, normalized_value ORDER BY id ASC ) AS rn FROM customer_memory_candidate WHERE status = 'PENDING' ) UPDATE customer_memory_candidate c SET status = 'EXPIRED' FROM ranked r WHERE c.id = r.id AND r.rn > 1;
